package vn.edu.eaut.lab8.model; import java.io.Serializable; public class Product implements Serializable {private int id,soLuong;private String tenSanPham;private double gia; public Product(){} public Product(int i,String t,double g,int s){id=i;tenSanPham=t;gia=g;soLuong=s;} public int getId(){return id;}public void setId(int v){id=v;}public String getTenSanPham(){return tenSanPham;}public void setTenSanPham(String v){tenSanPham=v;}public double getGia(){return gia;}public void setGia(double v){gia=v;}public int getSoLuong(){return soLuong;}public void setSoLuong(int v){soLuong=v;}}
